import React, { useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useLang } from '../LangContext';

const LANGS = [
  { code: 'en', label: 'EN' },
  { code: 'am', label: 'አማ' },
  { code: 'or', label: 'OR' },
];

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();
  const { lang, switchLang, t } = useLang();
  const user = JSON.parse(localStorage.getItem('user') || 'null');

  const logout = () => {
    localStorage.removeItem('userToken');
    localStorage.removeItem('user');
    navigate('/');
    window.location.reload();
  };

  const links = [
    { to: '/', label: t.home, end: true },
    { to: '/clients', label: t.clients },
    { to: '/news', label: t.news },
    { to: '/about', label: t.about },
    { to: '/contact', label: t.contact },
  ];

  const LangButtons = () => (
    <div className="lang-switcher">
      {LANGS.map(l => (
        <button
          key={l.code}
          className={`lang-btn${lang === l.code ? ' active' : ''}`}
          onClick={() => switchLang(l.code)}
        >
          {l.label}
        </button>
      ))}
    </div>
  );

  return (
    <nav className="navbar">
      <div className="navbar-inner">

        {/* Logo */}
        <NavLink to="/" className="nav-logo">
          All <span>Things</span>
        </NavLink>

        {/* Desktop links */}
        <div className="nav-desktop">
          {links.map(({ to, label, end }) => (
            <NavLink
              key={to}
              to={to}
              end={end}
              className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`}
            >
              {label}
            </NavLink>
          ))}

          {user ? (
            <>
              <NavLink
                to="/dashboard"
                className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`}
              >
                👤 {user.full_name?.split(' ')[0]}
              </NavLink>
              <button
                onClick={logout}
                style={{ padding: '8px 13px', background: 'none', border: 'none', color: '#ef4444', fontSize: 14, cursor: 'pointer' }}
              >
                {t.signOut}
              </button>
            </>
          ) : (
            <>
              <NavLink
                to="/login"
                className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`}
              >
                {t.signIn}
              </NavLink>
              <NavLink to="/register" className="nav-cta">
                {t.register}
              </NavLink>
            </>
          )}

          <div style={{ marginLeft: 10 }}>
            <LangButtons />
          </div>
        </div>

        {/* Mobile right side */}
        <div className="nav-mobile-right">
          <LangButtons />
          <button className="nav-burger" onClick={() => setOpen(!open)}>
            {open ? '✕' : '☰'}
          </button>
        </div>

      </div>

      {/* Mobile dropdown */}
      {open && (
        <div className="nav-mobile-menu">
          {links.map(({ to, label, end }) => (
            <NavLink
              key={to}
              to={to}
              end={end}
              onClick={() => setOpen(false)}
              className={({ isActive }) => `nav-mobile-link${isActive ? ' active' : ''}`}
            >
              {label}
            </NavLink>
          ))}

          {user ? (
            <>
              <NavLink
                to="/dashboard"
                onClick={() => setOpen(false)}
                className="nav-mobile-link"
              >
                👤 {t.myDashboard}
              </NavLink>
              <button
                onClick={logout}
                style={{ display: 'block', width: '100%', textAlign: 'left', padding: '12px 4px', background: 'none', border: 'none', color: '#ef4444', fontSize: 15, cursor: 'pointer', borderBottom: '1px solid #1a1a1a' }}
              >
                {t.signOut}
              </button>
            </>
          ) : (
            <div className="nav-mobile-btns">
              <NavLink to="/login" onClick={() => setOpen(false)} className="nav-mobile-signin">
                {t.signIn}
              </NavLink>
              <NavLink to="/register" onClick={() => setOpen(false)} className="nav-mobile-register">
                {t.register}
              </NavLink>
            </div>
          )}
        </div>
      )}
    </nav>
  );
}
